package com.example.techfix.adapters;

import android.view.LayoutInflater;import android.view.View;import android.view.ViewGroup;import android.widget.ImageView;import android.widget.TextView;
import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.example.techfix.R;import com.example.techfix.models.RepairService;import java.util.List;import java.util.Locale;
public class ServiceAdapter extends RecyclerView.Adapter<ServiceAdapter.Holder>{private List<RepairService> items;public ServiceAdapter(List<RepairService> items){this.items=items;}public void update(List<RepairService> value){items=value;notifyDataSetChanged();}@NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_service,p,false));}@Override public void onBindViewHolder(@NonNull Holder h,int i){RepairService s=items.get(i);h.name.setText(s.getName());h.category.setText(s.getCategory());h.price.setText(String.format(Locale.getDefault(),"Rs. %.2f",s.getPrice()));}@Override public int getItemCount(){return items.size();}static class Holder extends RecyclerView.ViewHolder{TextView name,category,price;ImageView image;Holder(View v){super(v);name=v.findViewById(R.id.tvServiceName);category=v.findViewById(R.id.tvServiceCategory);price=v.findViewById(R.id.tvServicePrice);image=v.findViewById(R.id.ivServiceImage);}}}
